pub fn all_modes()->Vec<ModeDefinition>{let mut v=MODES.to_vec();v.sort_by(|a,b|b.priority.cmp(&a.priority));v}
pub fn infer_mode_ids(goal:&str)->Vec<String>{let g=goal.to_lowercase();let mut ids:Vec<&str>=vec![];let has=|terms:&[&str]|terms.iter().any(|x|g.contains(x));if has(&["افحص جهازي","افحص الجهاز","فحص الجهاز","صحة الجهاز","حرارة الجهاز","device scan","system health","pc health","check my pc"]){ids.push("device")}if has(&["رانك","ranked","كود","call of duty","ألعب","العب","gaming","game"]){ids.extend(["gaming","device"])}if has(&["بث","تيك توك لايف","tiktok live","obs","stream","ستريم"]){ids.extend(["stream","device"])}if has(&["فيلم","مسلسل","مشاهدة","فاك شير","share play","watch party","cinema"]){ids.extend(["cinema","device"])}if has(&["دخل","فلوس","مال","ارباح","أرباح","بيع","منتج","وظيف","عمل عن بعد","revenue","money","sell","job","income"]){ids.extend(["money","internet","ceo"])}if has(&["برنامج","برمج","تطبيق","كود برمجي","ابنِ","ابني","build app","software","code"]){ids.extend(["builder","learn","lab"])}if has(&["نظف","تنظيف","رتب الجهاز","حذف برامج","ماله داعي","clean pc","debloat","housekeep"]){ids.extend(["housekeeper","device"])}if has(&["صمم","تصميم","هوية","thumbnail","creative","ui","ux"]){ids.push("creative")}if has(&["يوتيوب","محتوى","فيديو","video","youtube","content"]){ids.push("creator")}let mut seen=HashSet::new();ids.retain(|x|seen.insert(*x));if ids.is_empty(){ids.push("autopilot")}ids.into_iter().map(str::to_owned).collect()}
#[cfg(test)]mod tests{use super::*;#[test]fn registry_has_unique_ids(){let modes=all_modes();assert_eq!(modes.len(),24);let ids:HashSet<_>=modes.iter().map(|m|m.id).collect();assert_eq!(ids.len(),modes.len());assert_eq!(modes.first().unwrap().id,"crisis");}#[test]fn critical_user_modes_exist(){let ids:HashSet<_>=all_modes().iter().map(|m|m.id).collect();for id in ["device","gaming","stream","cinema","money","builder","internet","autopilot"]{assert!(ids.contains(id),"missing {id}")}}#[test]fn routes_device_ranked_stream_money_and_builder_intents(){assert_eq!(infer_mode_ids("افحص جهازي كامل"),vec!["device"]);assert_eq!(infer_mode_ids("أبي ألعب رانك كود"),vec!["gaming","device"]);assert_eq!(infer_mode_ids("أبي أبث على تيك توك لايف"),vec!["stream","device"]);assert_eq!(infer_mode_ids("أبي دخل وفلوس من الانترنت"),vec!["money","internet","ceo"]);assert_eq!(infer_mode_ids("ابنِ لي برنامج احترافي"),vec!["builder","learn","lab"]);}#[test]fn composes_stream_game_without_duplicates(){let x=infer_mode_ids("أبي أبث والعب كود");assert!(x.contains(&"gaming".into()));assert!(x.contains(&"stream".into()));assert_eq!(x.iter().filter(|v|v.as_str()=="device").count(),1);}}
